# stop-all.ps1 - stop all agents + Chrome (graceful)
# AUTO-GENERATED by Tools/gen_launchers.py. Do not edit by hand.
# Regenerate: python Tools/gen_launchers.py
$ErrorActionPreference = "Continue"
$Root = Split-Path -Parent $PSScriptRoot
$CfgFile = Join-Path $Root "config.json"
if (-not (Test-Path $CfgFile)) { Write-Host "config.json not found: $CfgFile" -ForegroundColor Red; exit 1 }
$Cfg = Get-Content $CfgFile -Raw | ConvertFrom-Json
$env:JEWAI_CONFIG = $CfgFile
function Log($m) { Write-Host ("[" + (Get-Date -Format "HH:mm:ss") + "] " + $m) }

Set-Location $Root
Log "stop-all: root=$Root"
$agents = Get-CimInstance Win32_Process -Filter "Name='python.exe' OR Name='pythonw.exe'" |
  Where-Object { $_.CommandLine -like "*Bridge\run.py*" -and $_.CommandLine -like "*$Root*" }
if ($agents) { Log "agents: $($agents.Count)"; $agents | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } }
$letters = @($Cfg.letters)
foreach ($L in $letters) {
  $prof = Join-Path $Root ('Profiles\' + $L + '\chrome')
  $ch = Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" | Where-Object { $_.CommandLine -like "*$prof*" }
  if ($ch) { Log "chrome-$L graceful: $($ch.Count)"; $ch | ForEach-Object { $p = Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue; if ($p) { $p.CloseMainWindow() | Out-Null } } }
}
Log "stop-all: done"
